ALTER TABLE  AUTORIZZAZIONI_SUBENTRI DROP COLUMN STAGIONALE_DA;
ALTER TABLE  AUTORIZZAZIONI_SUBENTRI DROP COLUMN STAGIONALE_A;

ALTER TABLE  AUTORIZZAZIONI_SUBENTRI add STAGIONALE_DA VARCHAR2(4);
ALTER TABLE  AUTORIZZAZIONI_SUBENTRI add STAGIONALE_A VARCHAR2(4);

UPDATE AUTORIZZAZIONI_SUBENTRI SET AUTORIZZAZIONI_SUBENTRI.STAGIONALE_DA = (SELECT AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA
                                  FROM AUTORIZZAZIONI_CONCESSIONI 
                                  WHERE AUTORIZZAZIONI_SUBENTRI.idcomune = AUTORIZZAZIONI_CONCESSIONI.idcomune and
                                  AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE )
WHERE AUTORIZZAZIONI_SUBENTRI.STAGIONALE_DA is null
AND EXISTS (SELECT 1
            FROM AUTORIZZAZIONI_CONCESSIONI 
            WHERE  AUTORIZZAZIONI_SUBENTRI.idcomune = AUTORIZZAZIONI_CONCESSIONI.idcomune and
                                  AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE);
                                  
  UPDATE AUTORIZZAZIONI_SUBENTRI SET AUTORIZZAZIONI_SUBENTRI.STAGIONALE_A = (SELECT AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA
  FROM AUTORIZZAZIONI_CONCESSIONI 
  WHERE AUTORIZZAZIONI_SUBENTRI.idcomune = AUTORIZZAZIONI_CONCESSIONI.idcomune and
                                  AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE )
WHERE AUTORIZZAZIONI_SUBENTRI.STAGIONALE_A is null
AND EXISTS (SELECT 1
            FROM AUTORIZZAZIONI_CONCESSIONI 
            WHERE  AUTORIZZAZIONI_SUBENTRI.idcomune = AUTORIZZAZIONI_CONCESSIONI.idcomune and
                                  AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE);


