CREATE OR REPLACE VIEW vw_istanzeconcessionilista AS SELECT 99999999 AS progressivo, autorizzazioni.autorizresponsabile AS conc_autorizresponsabile, autorizzazioni.idcomune, autorizzazioni.fk_causale_acquisizione AS iconc_codicecausale, nvl(autorizzazioni.data_cessazione,TO_DATE('31/12/9999','DD/MM/YYYY') ) AS data_storico, istanze.software, istanze.codiceistanza AS ist_codiceistanza, istanze.numeroistanza AS ist_numeroistanza, istanze.codicerichiedente AS ist_codicerichiedente, autorizzazioni.id AS conc_id, autorizzazioni.autoriznumero AS conc_numero, autorizzazioni.autorizdata AS conc_datavalidita, autorizzazioni.autorizdata AS datavalidita, autorizzazioni.data_rilascio AS conc_datarilascio, autorizzazioni.data_rilascio AS datarilascio, autorizzazioni.datascadenza AS conc_datascadenza, autorizzazioni_concessioni.fk_tipoconcessione AS conc_codicetipo, concessionitipi.descrizione AS conc_tipo, autorizzazioni_concessioni.stagionalea AS conc_stagionalea, autorizzazioni_concessioni.stagionaleda AS conc_stagionaleda, autorizzazioni.flag_attiva AS conc_attiva, autorizzazioni.fk_codiceanagrafe AS conc_codicetitolare, autorizzazioni.fkidregistro AS conc_fkidregistro, conc_registro.tr_descrizione AS conc_registro, titolare.nominativo || ' ' || titolare.nome AS conc_titolare, titolare.codicefiscale AS conc_tit_cf, titolare.partitaiva AS conc_tit_piva, titolare.tipoanagrafe AS conc_tit_tipoanagrafe, aut_collegata.autoriznumero AS aut_numero, aut_collegata.autorizdata AS aut_data, aut_collegata.autorizdata, aut_collegata.fkidregistro AS aut_codregistro, tipologiaregistri.tr_descrizione AS aut_registro, ist_richiedente.nominativo || ' ' || ist_richiedente.nome AS ist_nominativo, ist_richiedente.tipoanagrafe AS ist_ric_tipoanagrafe, ist_azienda.nominativo || ' ' || ist_azienda.nome AS ist_nominativoazienda, ist_azienda.tipoanagrafe AS ist_azi_tipoanagrafe, ist_richiedente.codicefiscale AS ist_codicefiscale, ist_richiedente.partitaiva AS ist_partitaiva, caus_attuale.descrizione AS iconc_causale, autorizzazioni.fk_causale_cessazione AS iconc_codicecausalestorico, caus_storico.descrizione AS iconc_causalestorico, autorizzazioni_concessioni.fk_codicemercato AS conc_idmercato, mercati.descrizione AS conc_mercato, mercati.attivo AS merc_attivo, autorizzazioni_concessioni.fk_idposteggio AS conc_idposteggio, mercati_d.codiceposteggio AS conc_posteggio, mercati_d.larghezza AS conc_pos_larghezza, mercati_d.lunghezza AS conc_pos_lunghezza, mercati_d.superficie AS conc_pos_superficie, mercati_d.fkcodicetipospazio AS post_idtipospazio, posteggitipospazio.tipospazio AS post_tipospazio, autorizzazioni_concessioni.fk_idmercatiuso AS conc_idmercatiuso, mercati_uso.descrizione AS conc_descrizioneuso, mercati_uso.peso AS peso_mercato, mercati_uso.fkcodiceuso AS merc_iduso, mercati_d.fkcodicestradario AS conc_pos_codicestradario, mercati_d.note AS conc_pos_note, vw_entilocali.comune AS conc_enterilascio FROM autorizzazioni INNER JOIN tipologiaregistri conc_registro ON autorizzazioni.idcomune = conc_registro.idcomune AND autorizzazioni.fkidregistro = conc_registro.tr_id INNER JOIN autorizzazioni_concessioni ON autorizzazioni.idcomune = autorizzazioni_concessioni.idcomune AND autorizzazioni.id = autorizzazioni_concessioni.fk_idaut_attuale LEFT JOIN autorizzazioni aut_collegata ON autorizzazioni_concessioni.idcomune = aut_collegata.idcomune AND autorizzazioni_concessioni.fk_idaut_collegata = aut_collegata.id LEFT JOIN tipologiaregistri ON aut_collegata.idcomune = tipologiaregistri.idcomune AND aut_collegata.fkidregistro = tipologiaregistri.tr_id INNER JOIN concessionitipi ON autorizzazioni_concessioni.fk_tipoconcessione = concessionitipi.tipoconcessione INNER JOIN anagrafe titolare ON autorizzazioni.idcomune = titolare.idcomune AND autorizzazioni.fk_codiceanagrafe = titolare.codiceanagrafe INNER JOIN concessionicausali caus_attuale ON autorizzazioni.idcomune = caus_attuale.idcomune AND autorizzazioni.fk_causale_acquisizione = caus_attuale.codicecausale LEFT JOIN concessionicausali caus_storico ON autorizzazioni.idcomune = caus_storico.idcomune AND autorizzazioni.fk_causale_cessazione = caus_storico.codicecausale INNER JOIN istanze ON autorizzazioni.idcomune = istanze.idcomune AND autorizzazioni.fkidistanza = istanze.codiceistanza INNER JOIN anagrafe ist_richiedente ON istanze.idcomune = ist_richiedente.idcomune AND istanze.codicerichiedente = ist_richiedente.codiceanagrafe INNER JOIN mercati ON autorizzazioni_concessioni.idcomune = mercati.idcomune AND autorizzazioni_concessioni.fk_codicemercato = mercati.codicemercato INNER JOIN mercati_d ON autorizzazioni_concessioni.idcomune = mercati_d.idcomune AND autorizzazioni_concessioni.fk_idposteggio = mercati_d.idposteggio LEFT JOIN posteggitipospazio ON mercati_d.idcomune = posteggitipospazio.idcomune AND mercati_d.fkcodicetipospazio = posteggitipospazio.codice INNER JOIN mercati_uso ON autorizzazioni_concessioni.idcomune = mercati_uso.idcomune AND autorizzazioni_concessioni.fk_idmercatiuso = mercati_uso.id LEFT JOIN anagrafe ist_azienda ON istanze.idcomune = ist_azienda.idcomune AND istanze.codicetitolarelegale = ist_azienda.codiceanagrafe INNER JOIN vw_entilocali ON autorizzazioni.autorizcomune = vw_entilocali.codicecomune UNION SELECT autorizzazioni_subentri.id AS progressivo, autorizzazioni_subentri.autorizresponsabile AS conc_autorizresponsabile, autorizzazioni_subentri.idcomune, autorizzazioni_subentri.fk_causale_acquisizione AS iconc_codicecausale, autorizzazioni_subentri.data_cessazione AS data_storico, istanze.software, istanze.codiceistanza AS ist_codiceistanza, istanze.numeroistanza AS ist_numeroistanza, istanze.codicerichiedente AS ist_codicerichiedente, autorizzazioni_subentri.fk_idaut_attuale AS conc_id, autorizzazioni_subentri.autoriznumero AS conc_numero, autorizzazioni_subentri.autorizdata AS conc_datavalidita, autorizzazioni_subentri.autorizdata AS datavalidita, autorizzazioni_subentri.data_rilascio AS conc_datarilascio, autorizzazioni_subentri.data_rilascio AS datarilascio, autorizzazioni_subentri.datascadenza AS conc_datascadenza, autorizzazioni_subentri_conc.fk_tipoconcessione AS conc_codicetipo, concessionitipi.descrizione AS conc_tipo, autorizzazioni_subentri_conc.stagionalea AS conc_stagionalea, autorizzazioni_subentri_conc.stagionaleda AS conc_stagionaleda, 0 AS conc_attiva, autorizzazioni_subentri.fk_codiceanagrafe AS conc_codicetitolare, autorizzazioni_subentri.fkidregistro AS conc_fkidregistro, conc_registro.tr_descrizione AS conc_registro, titolare.nominativo || ' ' || titolare.nome AS conc_titolare, titolare.codicefiscale AS conc_tit_cf, titolare.partitaiva AS conc_tit_piva, titolare.tipoanagrafe AS conc_tit_tipoanagrafe, aut_collegata.autoriznumero AS aut_numero, aut_collegata.autorizdata AS aut_data, aut_collegata.autorizdata, aut_collegata.fkidregistro AS aut_codregistro, tipologiaregistri.tr_descrizione AS aut_registro, ist_richiedente.nominativo || ' ' || ist_richiedente.nome AS ist_nominativo, ist_richiedente.tipoanagrafe AS ist_ric_tipoanagrafe, ist_azienda.nominativo || ' ' || ist_azienda.nome AS ist_nominativoazienda, ist_azienda.tipoanagrafe AS ist_azi_tipoanagrafe, ist_richiedente.codicefiscale AS ist_codicefiscale, ist_richiedente.partitaiva AS ist_partitaiva, caus_attuale.descrizione AS iconc_causale, autorizzazioni_subentri.fk_causale_cessazione AS iconc_codicecausalestorico, caus_storico.descrizione AS iconc_causalestorico, autorizzazioni_subentri_conc.fk_codicemercato AS conc_idmercato, mercati.descrizione AS conc_mercato, mercati.attivo AS merc_attivo, autorizzazioni_subentri_conc.fk_idposteggio AS conc_idposteggio, mercati_d.codiceposteggio AS conc_posteggio, mercati_d.larghezza AS conc_pos_larghezza, mercati_d.lunghezza AS conc_pos_lunghezza, mercati_d.superficie AS conc_pos_superficie, mercati_d.fkcodicetipospazio AS post_idtipospazio, posteggitipospazio.tipospazio AS post_tipospazio, autorizzazioni_subentri_conc.fk_idmercatiuso AS conc_idmercatiuso, mercati_uso.descrizione AS conc_descrizioneuso, mercati_uso.peso AS peso_mercato, mercati_uso.fkcodiceuso AS merc_iduso, mercati_d.fkcodicestradario AS conc_pos_codicestradario, mercati_d.note AS conc_pos_note, vw_entilocali.comune AS conc_enterilascio FROM autorizzazioni_subentri INNER JOIN tipologiaregistri conc_registro ON autorizzazioni_subentri.idcomune = conc_registro.idcomune AND autorizzazioni_subentri.fkidregistro = conc_registro.tr_id INNER JOIN autorizzazioni_subentri_conc ON autorizzazioni_subentri.idcomune = autorizzazioni_subentri_conc.idcomune AND autorizzazioni_subentri.id = autorizzazioni_subentri_conc.fk_autsub_id LEFT JOIN autorizzazioni_subentri aut_collegata ON autorizzazioni_subentri_conc.idcomune = aut_collegata.idcomune AND autorizzazioni_subentri_conc.fk_idautsub_autcoll = aut_collegata.id LEFT JOIN tipologiaregistri ON aut_collegata.idcomune = tipologiaregistri.idcomune AND aut_collegata.fkidregistro = tipologiaregistri.tr_id INNER JOIN concessionitipi ON autorizzazioni_subentri_conc.fk_tipoconcessione = concessionitipi.tipoconcessione INNER JOIN anagrafe titolare ON autorizzazioni_subentri.idcomune = titolare.idcomune AND autorizzazioni_subentri.fk_codiceanagrafe = titolare.codiceanagrafe INNER JOIN concessionicausali caus_attuale ON autorizzazioni_subentri.idcomune = caus_attuale.idcomune AND autorizzazioni_subentri.fk_causale_acquisizione = caus_attuale.codicecausale LEFT JOIN concessionicausali caus_storico ON autorizzazioni_subentri.idcomune = caus_storico.idcomune AND autorizzazioni_subentri.fk_causale_cessazione = caus_storico.codicecausale INNER JOIN istanze ON autorizzazioni_subentri.idcomune = istanze.idcomune AND autorizzazioni_subentri.fkidistanza = istanze.codiceistanza INNER JOIN anagrafe ist_richiedente ON istanze.idcomune = ist_richiedente.idcomune AND istanze.codicerichiedente = ist_richiedente.codiceanagrafe INNER JOIN mercati ON autorizzazioni_subentri_conc.idcomune = mercati.idcomune AND autorizzazioni_subentri_conc.fk_codicemercato = mercati.codicemercato INNER JOIN mercati_d ON autorizzazioni_subentri_conc.idcomune = mercati_d.idcomune AND autorizzazioni_subentri_conc.fk_idposteggio = mercati_d.idposteggio LEFT JOIN posteggitipospazio ON mercati_d.idcomune = posteggitipospazio.idcomune AND mercati_d.fkcodicetipospazio = posteggitipospazio.codice INNER JOIN mercati_uso ON autorizzazioni_subentri_conc.idcomune = mercati_uso.idcomune AND autorizzazioni_subentri_conc.fk_idmercatiuso = mercati_uso.id LEFT JOIN anagrafe ist_azienda ON istanze.idcomune = ist_azienda.idcomune AND istanze.codicetitolarelegale = ist_azienda.codiceanagrafe INNER JOIN vw_entilocali ON autorizzazioni_subentri.autorizcomune = vw_entilocali.codicecomune;

CREATE OR REPLACE VIEW vw_concessionilista AS SELECT idcomune, software, progressivo, conc_id, conc_numero, conc_datavalidita, conc_datarilascio, conc_datascadenza, conc_codicetipo, conc_tipo, conc_stagionalea, conc_stagionaleda, conc_attiva, conc_codicetitolare, conc_titolare, conc_tit_cf, conc_tit_piva, conc_tit_tipoanagrafe, conc_fkidregistro, conc_registro, aut_numero, aut_data, aut_codregistro, aut_registro, ist_codiceistanza, ist_numeroistanza, ist_codicerichiedente, ist_nominativo, ist_codicefiscale, ist_partitaiva, ist_ric_tipoanagrafe, iconc_codicecausale, iconc_causale, iconc_codicecausalestorico, iconc_causalestorico, conc_idmercato, conc_mercato, merc_attivo, conc_idposteggio, conc_posteggio, conc_pos_larghezza, conc_pos_lunghezza, conc_pos_superficie, post_idtipospazio, post_tipospazio, conc_idmercatiuso, conc_descrizioneuso, peso_mercato, merc_iduso, conc_pos_codicestradario, data_storico, conc_enterilascio FROM vw_istanzeconcessionilista;


